'use client';

import { createElement, useState } from 'react';

export function NodeModulesCounter() {
  const [count, setCount] = useState(0);

  return createElement(
    'button',
    {
      type: 'button',
      'data-testid': 'node-modules-counter',
      onClick() {
        setCount(count + 1);
      },
    },
    'Node modules count: ' + count,
  );
}
